<script setup lang="ts">import {reactive,ref,onMounted} from 'vue';import {specs} from '../stores/specs';import {canWrite} from '../stores/auth';import {properties,propertyLabels} from '../constants/enums';import {useTask} from '../hooks/useTask';import {pct} from '../utils/format';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';const name=ref(''),description=ref(''),limits=reactive<Record<string,number>>({strength_min:70,strength_max:100,whiteness_min:80,whiteness_max:100,recycled_min:.25,recycled_max:1});const {error,busy,act}=useTask();onMounted(specs.load);function submit(){act(async()=>{await specs.create({name:name.value,...limits,description:description.value});name.value=''})}</script><template><PageHeading index="02 / 质量窗口" title="把配方要守住的界限，逐项写清。" note="质量属性按配方比例线性加权仅为此模拟模型的假设。上下界必须有序且在声明物理范围内。"/><div class="two-col"><section><article v-for="r in specs.items.value" :key="r.id" class="spec-row"><p class="eyebrow">QUALITY SPECIFICATION</p><h2>{{r.name}}</h2><div class="table-wrap"><table><thead><tr><th>属性</th><th>下界</th><th>上界</th></tr></thead><tbody><tr v-for="key in properties" :key="key"><td>{{propertyLabels[key]}}</td><td>{{key==='recycled'?pct(r[key+'_min']):r[key+'_min']}}</td><td>{{key==='recycled'?pct(r[key+'_max']):r[key+'_max']}}</td></tr></tbody></table></div><p>{{r.description}}</p></article></section><form v-if="canWrite()" class="editor-panel" @submit.prevent="submit"><h2>新增质量窗口</h2><label>窗口名称<input v-model="name" required minlength="2"></label><div v-for="key in properties" :key="key" class="form-pair"><label>{{propertyLabels[key]}}下界<input type="number" v-model.number="limits[key+'_min']" min="0" :max="key==='recycled'?1:100" step="any"></label><label>上界<input type="number" v-model.number="limits[key+'_max']" min="0" :max="key==='recycled'?1:100" step="any"></label></div><label>口径说明<textarea v-model="description" rows="3"></textarea></label><Notice :message="error"/><button :disabled="busy">保存质量窗口</button></form></div></template>
